// Pure scoring module (PRD §6). No DOM/framework dependencies.
export const DECISION_POINTS = { YES: 3, CORRECTIVE: 1, NO: 0 };

function emptyScope() { return { points: 0, maxPoints: 0, percent: 0, scoredCount: 0, questionCount: 0 }; }

/** decisions: questionId -> 'YES'|'CORRECTIVE'|'NO' (missing = unscored) */
export function scoreAssessment(bank, decisions) {
  const overall = emptyScope(), byIndicator = {}, bySubIndicator = {};
  for (const ind of bank.indicators) byIndicator[ind.id] = emptyScope();
  for (const s of bank.sub_indicators) bySubIndicator[s.id] = emptyScope();
  for (const q of bank.questions) {
    const d = decisions[q.id];
    const pts = d ? DECISION_POINTS[d] * q.priority : 0;
    for (const sc of [overall, byIndicator[q.indicator_id], bySubIndicator[q.sub_indicator_id]]) {
      sc.maxPoints += 3 * q.priority; sc.questionCount++;
      if (d) { sc.points += pts; sc.scoredCount++; }
    }
  }
  for (const sc of [overall, ...Object.values(byIndicator), ...Object.values(bySubIndicator)])
    sc.percent = sc.maxPoints ? (sc.points / sc.maxPoints) * 100 : 0;
  return { overall, byIndicator, bySubIndicator, unscoredCount: overall.questionCount - overall.scoredCount };
}

/** Assessee-side completeness (PRD §7.3) */
export const MIN_ANSWER_CHARS = 20;
export function isComplete(response) {
  return !!response && (response.text || '').trim().length >= MIN_ANSWER_CHARS;
}
